-- INPC number index (IBGE SIDRA, table 1736, variable 2289, base dez/1993 = 100), fetched 2026-09-27, 1994-06 to 2026-08.
-- Published months never change, so the table is append-only; a new month is a new migration.
CREATE TRIGGER inpc_indice_append_only BEFORE UPDATE OR DELETE ON inpc_indice FOR EACH ROW EXECUTE FUNCTION append_only();
